begin;
select set_config('biome.test_a',gen_random_uuid()::text,true),set_config('biome.test_b',gen_random_uuid()::text,true),set_config('biome.test_c',gen_random_uuid()::text,true);
insert into auth.users(id) values(current_setting('biome.test_a')::uuid),(current_setting('biome.test_b')::uuid),(current_setting('biome.test_c')::uuid);
insert into public.biome_profiles(id,username) select current_setting('biome.test_a')::uuid,'TestA_'||left(current_setting('biome.test_a'),8) union all select current_setting('biome.test_b')::uuid,'TestB_'||left(current_setting('biome.test_b'),8) union all select current_setting('biome.test_c')::uuid,'TestC_'||left(current_setting('biome.test_c'),8);
set local role authenticated;
select set_config('request.jwt.claim.sub',current_setting('biome.test_a'),true);
select public.biome_request_friend(lower('TestB_'||left(current_setting('biome.test_b'),8)));
do $$begin if (select count(*) from public.biome_friends where requester=auth.uid())<>1 then raise exception 'Friend request failed';end if;end;$$;
select set_config('request.jwt.claim.sub',current_setting('biome.test_c'),true);
do $$begin if exists(select 1 from public.biome_friends where requester=current_setting('biome.test_a')::uuid) then raise exception 'Friend graph leaked to another user';end if;end;$$;
select set_config('request.jwt.claim.sub',current_setting('biome.test_b'),true);
select public.biome_accept_friend((select id from public.biome_friends where requester=current_setting('biome.test_a')::uuid));
select set_config('request.jwt.claim.sub',current_setting('biome.test_a'),true);
insert into public.biome_online_worlds(host_id,lobby_id,world_name,access) values(auth.uid(),'testlobby123456789','Test world','friends');
select set_config('request.jwt.claim.sub',current_setting('biome.test_b'),true);
do $$begin if not exists(select 1 from public.biome_online_worlds where host_id=current_setting('biome.test_a')::uuid) then raise exception 'Accepted friend cannot see friends world';end if;end;$$;
select set_config('request.jwt.claim.sub',current_setting('biome.test_c'),true);
do $$begin if exists(select 1 from public.biome_online_worlds where host_id=current_setting('biome.test_a')::uuid) then raise exception 'World leaked to nonfriend';end if;end;$$;
select set_config('request.jwt.claim.sub',current_setting('biome.test_a'),true);
update public.biome_online_worlds set access='invite' where host_id=auth.uid();
select set_config('request.jwt.claim.sub',current_setting('biome.test_b'),true);
do $$begin if exists(select 1 from public.biome_online_worlds where host_id=current_setting('biome.test_a')::uuid) then raise exception 'Invite-only world leaked before invitation';end if;end;$$;
select set_config('request.jwt.claim.sub',current_setting('biome.test_a'),true);
insert into public.biome_world_invites(host_id,guest_id) values(auth.uid(),current_setting('biome.test_b')::uuid);
select set_config('request.jwt.claim.sub',current_setting('biome.test_b'),true);
do $$begin if not exists(select 1 from public.biome_online_worlds where host_id=current_setting('biome.test_a')::uuid) then raise exception 'Invited friend cannot see world';end if;end;$$;
reset role;
do $$begin if has_table_privilege('anon','public.biome_friends','SELECT') or has_table_privilege('anon','public.biome_online_worlds','SELECT') then raise exception 'Anonymous access enabled';end if;end;$$;
rollback;
select 'PASS: requests, acceptance, private friend graphs, friends-only visibility, invite-only visibility, and anonymous denial. All fixtures rolled back.' as result;
